const { chromium } = playwright;
const browser = await chromium.launch({ headless: true });
const page = await browser.newPage({ viewport: { width: 1400, height: 900 } });
const invokes = [];
page.on("pageerror", (error) => console.log("PAGEERROR", error.message));
page.on("console", (msg) => {
  if (msg.type() === "error") console.log("CONSOLE", msg.text());
});

await page.addInitScript(() => {
  const callbacks = new Map();
  window.__TAURI_INTERNALS__ = {
    invoke: async (cmd, args = {}) => {
      window.__QA_INVOKES__ = window.__QA_INVOKES__ || [];
      window.__QA_INVOKES__.push({ cmd, url: args?.request?.url ?? args?.url ?? null });
      if (cmd === "cmd_project_initial" || cmd === "cmd_project_register") {
        return { workspaceId: "orca-lite", repoRoot: "/tmp/orca-lite" };
      }
      if (cmd === "cmd_worktree_list") {
        return [{ path: "/tmp/orca-lite", branch: "refs/heads/main", head: "abc", isMain: true, isLocked: false }];
      }
      if (cmd === "cmd_session_load") return null;
      if (cmd === "cmd_session_save" || cmd === "cmd_session_clear") return null;
      if (cmd === "cmd_terminal_list") return [];
      if (cmd === "cmd_terminal_spawn") return { sessionId: "term-1" };
      if (cmd === "cmd_terminal_preferences") {
        return {
          fontFamily: "monospace",
          fontSize: 13,
          macosOptionAsAlt: false,
          cursorStyle: "block",
          theme: { background: "#282c34", foreground: "#d4d4d4" },
          source: "defaults",
          status: "absent",
          sourcePath: null,
        };
      }
      if (cmd === "cmd_agents_detect") return [];
      if (cmd === "cmd_browser_create") {
        return {
          browserId: "browser-qa",
          webviewLabel: "browser-qa",
          workspaceId: "orca-lite",
          worktreePath: "/tmp/orca-lite",
          profileId: "default",
          generation: 1,
          url: args.request.url,
          title: null,
          loading: false,
          canGoBack: false,
          canGoForward: false,
          zoomFactor: 1,
          loadError: null,
          visible: true,
        };
      }
      if (cmd === "plugin:event|listen") return 1;
      if (cmd === "plugin:event|unlisten") return null;
      return null;
    },
    transformCallback: (callback) => {
      const id = callbacks.size + 1;
      callbacks.set(id, callback);
      return id;
    },
    unregisterCallback: (id) => {
      callbacks.delete(id);
    },
    convertFileSrc: (filePath) => filePath,
    metadata: { currentWindow: { label: "main" } },
  };
});

async function openNewBrowserTab(label) {
  const newTab = page.getByRole("button", { name: "New tab" });
  await newTab.first().click();
  await page.getByRole("button", { name: /New Browser Tab/i }).click();
  await page.waitForSelector('[data-testid="browser-viewport"]', { timeout: 5000 });
  const tabs = await page.locator('[role="tab"]').allTextContents();
  const address = await page.locator("input").inputValue().catch(() => "");
  const invokesNow = await page.evaluate(() => window.__QA_INVOKES__ || []);
  await page.screenshot({ path: `/tmp/new-browser-tab-qa-${label}.png`, fullPage: true });
  console.log(label, JSON.stringify({ tabs, address, invokes: invokesNow.filter((item) => item.cmd === "cmd_browser_create") }));
}

await page.goto("http://127.0.0.1:5173/", { waitUntil: "networkidle" });
await page.screenshot({ path: "/tmp/new-browser-tab-qa-initial.png", fullPage: true });
console.log("BODY", (await page.locator("body").innerText()).slice(0, 1500));
console.log("BUTTONS", await page.locator("button").evaluateAll((els) => els.map((el) => el.textContent?.trim()).filter(Boolean)));

try {
  await openNewBrowserTab("blank");
} catch (error) {
  console.log("BLANK_FAIL", error instanceof Error ? error.message : String(error));
}

await page.evaluate(() => {
  localStorage.setItem("ferryx.browser.v1", JSON.stringify({ homePage: "https://example.com/start" }));
});
await page.reload({ waitUntil: "networkidle" });
try {
  await openNewBrowserTab("homepage");
} catch (error) {
  console.log("HOMEPAGE_FAIL", error instanceof Error ? error.message : String(error));
}

console.log("INVOKES", JSON.stringify(invokes));
await browser.close();

